	}
	raw, err := json.Marshal(claims)
	if err != nil || !hmac.Equal(claims.seal[:], c.mac("verified", raw)) {
		return ErrCursorInvalid
	}
	if err := c.checkTime(claims); err != nil {
		return err
	}
	if err := runCursorGuard(ctx, guard, claims.Binding); err != nil {
